# test_truncate.py
import pytest

# Replace this import with the actual module name.
# from your_module import truncate


def truncate(s: str, max_len: int, suffix: str = "...") -> str:
    if len(s) <= max_len:
        return s
    return s[:max_len - len(suffix)] + suffix


@pytest.mark.parametrize(
    "s,max_len,expected",
    [
        ("hello", 10, "hello"),      # shorter than max_len
        ("hello", 5, "hello"),       # exactly max_len
        ("hello world", 8, "hello..."),
        ("abcdef", 4, "a..."),
    ],
)
def test_truncate_default_suffix(s, max_len, expected):
    assert truncate(s, max_len) == expected


@pytest.mark.parametrize(
    "s,max_len,suffix,expected",
    [
        ("hello world", 8, "..", "hello .."),
        ("hello world", 8, "!", "hello w!"),
        ("hello world", 5, "--", "hel--"),
        ("abcdef", 3, "", "abc"),
    ],
)
def test_truncate_custom_suffix(s, max_len, suffix, expected):
    assert truncate(s, max_len, suffix) == expected


def test_truncate_empty_string():
    assert truncate("", 5) == ""


def test_truncate_when_suffix_length_equals_max_len():
    assert truncate("abcdef", 3, "...") == "..."


def test_truncate_unicode_characters():
    assert truncate("こんにちは世界", 6, "...") == "こんに..."


@pytest.mark.parametrize(
    "s,max_len,suffix,expected",
    [
        ("abcdef", 2, "...", "abc..."),
        ("abcdef", 0, "...", "abc..."),
        ("abcdef", -1, "...", "ab..."),
    ],
)
def test_truncate_when_max_len_is_less_than_suffix_length_current_behavior(
    s,
    max_len,
    suffix,
    expected,
):
    """
    Documents the current behavior.

    Note: these results may be surprising because the returned string can be
    longer than max_len when max_len < len(suffix).
    """
    assert truncate(s, max_len, suffix) == expected


def test_truncate_raises_type_error_when_s_is_none():
    with pytest.raises(TypeError):
        truncate(None, 5)


def test_truncate_raises_type_error_when_max_len_is_not_int():
    with pytest.raises(TypeError):
        truncate("hello", "5")


def test_truncate_raises_type_error_when_suffix_is_none_and_truncation_needed():
    with pytest.raises(TypeError):
        truncate("hello world", 5, None)


def test_truncate_does_not_use_invalid_suffix_if_no_truncation_needed():
    assert truncate("hello", 10, None) == "hello"
